contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 fund, uint256 amount, address adr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund) + (amount)); require(fund <= 1000000000000000000000000000000); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= fund + amount);
        require(amount < fund);
        c.Command(address(c), ""); if (__ESBMC_reverted()) return;
        c.Command{value: fund}(address(c), ""); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        c.multiplicate{value: amount}(adr); if (__ESBMC_reverted()) return;
        assert(address(c).balance == balBefore + amount);
    }
    receive() external payable {}
}

